+// --- Participation toggle ---
+
+interface ParticipationToggleProps {
+  platformName: string
+  enabled: boolean
+  /** Disabled until a link is present — a network can't be ON without one. */
+  hasLink: boolean
+  onToggle: (enabled: boolean) => void
+}
+
+function ParticipationToggle({ platformName, enabled, hasLink, onToggle }: ParticipationToggleProps) {
+  return (
+    <div className="flex items-center gap-2">
+      <Switch
+        checked={enabled}
+        disabled={!hasLink}
+        onCheckedChange={onToggle}
+        aria-label={`Activer la mise en relation pour ${platformName}`}
+      />
+      <span className={`text-xs font-medium ${enabled ? "text-foreground" : "text-muted-foreground"}`}>
+        {enabled ? "Activé" : "Désactivé"}
+      </span>
+    </div>
+  )
+}
